#!/usr/bin/env node
// Resolves the design tokens out of globals.css for both themes and measures
// the WCAG contrast of every pair declared in docs/design/tokens.pairs.json.
// Nothing here is asserted by hand: the ratios in the design system document
// are generated by this file.
//
//   node docs/design/verification/contrast.mjs            table for both themes
//   node docs/design/verification/contrast.mjs --json     machine readable
//   node docs/design/verification/contrast.mjs --markdown table for the document
import { readFileSync } from "node:fs";

const CSS = "src/app/globals.css";
const PAIRS = "docs/design/tokens.pairs.json";

// ---- token extraction ----
// `:root { ... }` is the light theme, `.dark { ... }` the dark one. Only the
// first block of each is read; later blocks in the file are utilities.
function block(css, selector) {
  // Anchored at line start: a bare indexOf(".dark") also matches the
  // `@custom-variant dark (&:where(.dark, .dark *))` line near the top and
  // would silently extract the wrong block, reporting light values as dark.
  const re = new RegExp(`^${selector.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\s*\\{`, "m");
  const m = css.match(re);
  if (!m) throw new Error(`no ${selector} block in ${CSS}`);
  const i = m.index;
  const open = css.indexOf("{", i);
  let depth = 0;
  for (let j = open; j < css.length; j++) {
    if (css[j] === "{") depth++;
    else if (css[j] === "}") { depth--; if (depth === 0) return css.slice(open + 1, j); }
  }
  throw new Error(`unbalanced ${selector}`);
}

function vars(text) {
  const out = new Map();
  for (const m of text.matchAll(/(--[\w-]+)\s*:\s*([^;]+);/g)) out.set(m[1], m[2].trim());
  return out;
}

function resolve(map, name, seen = new Set()) {
  if (seen.has(name)) return null;
  seen.add(name);
  let v = map.get(name);
  if (!v) return null;
  const ref = v.match(/^var\(\s*(--[\w-]+)\s*\)$/);
  if (ref) return resolve(map, ref[1], seen);
  return v;
}

// ---- colour ----
function parse(v) {
  if (!v) return null;
  let s = v.trim();
  let m = s.match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/i);
  if (m) {
    let h = m[1];
    if (h.length === 3) h = h.split("").map((c) => c + c).join("");
    return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)];
  }
  m = s.match(/^rgba?\(([^)]+)\)$/i);
  if (m) {
    const p = m[1].split(/[,\s/]+/).filter(Boolean).map(Number);
    if (p.length >= 3) return [p[0], p[1], p[2]];
  }
  return null;
}

const lin = (c) => { c /= 255; return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4); };
const lum = ([r, g, b]) => 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
export function ratio(a, b) {
  const L1 = lum(a), L2 = lum(b);
  return (Math.max(L1, L2) + 0.05) / (Math.min(L1, L2) + 0.05);
}

// ---- run ----
const css = readFileSync(CSS, "utf8");
const themes = {
  light: vars(block(css, ":root")),
  dark: new Map([...vars(block(css, ":root")), ...vars(block(css, ".dark"))]),
};
const pairs = JSON.parse(readFileSync(PAIRS, "utf8"));

const rows = [];
let failures = 0;
for (const p of pairs.pairs) {
  for (const theme of p.themes || ["light", "dark"]) {
    const map = themes[theme];
    const fgv = resolve(map, p.fg), bgv = resolve(map, p.bg);
    const fg = parse(fgv), bg = parse(bgv);
    if (!fg || !bg) {
      rows.push({ theme, fg: p.fg, bg: p.bg, use: p.use, min: p.min, ratio: null, pass: false, why: `unresolved (${p.fg}=${fgv}, ${p.bg}=${bgv})` });
      failures++;
      continue;
    }
    const r = Math.round(ratio(fg, bg) * 100) / 100;
    const pass = r + 0.005 >= p.min;
    if (!pass) failures++;
    rows.push({ theme, fg: p.fg, bg: p.bg, use: p.use, min: p.min, ratio: r, pass, fgv, bgv });
  }
}

if (process.argv.includes("--json")) {
  console.log(JSON.stringify({ failures, rows }, null, 2));
} else if (process.argv.includes("--markdown")) {
  for (const theme of ["light", "dark"]) {
    console.log(`\n### ${theme[0].toUpperCase() + theme.slice(1)} theme\n`);
    console.log("| Foreground | Background | Use | Required | Measured |");
    console.log("|---|---|---|---|---|");
    for (const r of rows.filter((x) => x.theme === theme))
      console.log(`| \`${r.fg}\` | \`${r.bg}\` | ${r.use} | ${r.min.toFixed(1)} | ${r.ratio === null ? "unresolved" : r.ratio.toFixed(2)} |`);
  }
} else {
  for (const r of rows) {
    const mark = r.pass ? "ok  " : "FAIL";
    console.log(`${mark} ${r.theme.padEnd(5)} ${String(r.ratio ?? "?").padStart(6)} need ${r.min}  ${r.fg} on ${r.bg}  ${r.why || ""}`);
  }
  console.log(`\n${rows.length} pairs measured, ${failures} below requirement`);
}
process.exit(failures ? 1 : 0);
